import sys
from itertools import combinations

def mean(nums):
    return sum(nums) / len(nums)

def median(nums):
    nums = sorted(nums)
    mid = len(nums) // 2
    if len(nums) % 2 == 0:
        return (nums[mid - 1] + nums[mid]) / 2
    else:
        return nums[mid]

def range_(nums):
    return max(nums) - min(nums)

def find_missing_boxes(n, a):
    if n == 4:
        return "YES", []

    for missing in combinations(range(1, 10**6 + 1), 4 - n):
        all_boxes = a + list(missing)
        if mean(all_boxes) == median(all_boxes) == range_(all_boxes):
            return "YES", missing

    return "NO", []

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
